#include <iostream>
#include <cstdio>
#include <algorithm>
#include <vector>
#include <cstring>
#include <queue>
using namespace std;
using db = double;
using ll = long long;
using ull = unsigned long long;
using pii = pair<int, int>;
using pis = pair<int, string>;
#define mp make_pair
#define pb push_back
const int N = 11;
const int INF = 1e9;
const int SIZE = 2 * N * N;

struct Edge
{
  int destination, capacity, flow, reverseIndex;
  Edge() {}
  Edge(int d, int c, int f, int r) : destination(d), capacity(c), flow(f), reverseIndex(r) {}
};

vector<Edge> graph[SIZE];
int distance[SIZE], pointer[SIZE], source, sink, gridSize;
queue<int> levelQueue;

void insertEdge(int u, int v, int cap)
{
  graph[u].emplace_back(v, cap, 0, 0);
  graph[v].emplace_back(u, 0, 0, 0);
  graph[u].back().reverseIndex = graph[v].size() - 1;
  graph[v].back().reverseIndex = graph[u].size() - 1;
}

bool constructLevelGraph()
{
  fill(distance, distance + sink + 1, INF);
  distance[source] = 0;
  levelQueue.push(source);
  while (!levelQueue.empty())
  {
    int current = levelQueue.front();
    levelQueue.pop();
    for (auto& e : graph[current])
    {
      int nextNode = e.destination;
      int residual = e.capacity - e.flow;
      if (distance[nextNode] == INF && residual > 0)
      {
        distance[nextNode] = distance[current] + 1;
        levelQueue.push(nextNode);
      }
    }
  }
  return distance[sink] != INF;
}

int dfsBlock(int node, int minFlow)
{
  if (node == sink) return minFlow;
  for (int& i = pointer[node]; i < graph[node].size(); ++i)
  {
    auto& e = graph[node][i];
    int nextNode = e.destination;
    int residual = e.capacity - e.flow, additionalFlow;
    if (distance[nextNode] == distance[node] + 1 && residual > 0 && (additionalFlow = dfsBlock(nextNode, min(minFlow, residual))))
    {
      e.flow += additionalFlow;
      graph[nextNode][e.reverseIndex].flow -= additionalFlow;
      return additionalFlow;
    }
  }
  return 0;
}

int dinicAlgorithm()
{
  int totalFlow = 0;
  while (constructLevelGraph())
  {
    memset(pointer, 0, sizeof(pointer));
    int increment;
    while ((increment = dfsBlock(source, INF)))
      totalFlow += increment;
  }
  return totalFlow;
}

queue<pii> bfsQueue;
const int dx[] = {-1, 1, 0, 0};
const int dy[] = {0, 0, -1, 1};
int distances[N][N][N][N], threshold;
char gridA[N][N], gridB[N][N];
pii obstacle;
bool isValid(pii pos)
{
  return pos.first >= 0 && pos.first < gridSize && pos.second >= 0 && pos.second < gridSize && gridA[pos.first][pos.second] != 'Y' && gridA[pos.first][pos.second] != 'Z';
}
void bfs(int startX, int startY)
{
  for (int i = 0; i < gridSize; ++i)
    for (int j = 0; j < gridSize; ++j)
      distances[startX][startY][i][j] = INF;
  distances[startX][startY][startX][startY] = 0;
  bfsQueue.emplace(startX, startY);
  while (!bfsQueue.empty())
  {
    pii current = bfsQueue.front();
    bfsQueue.pop();
    if (distances[startX][startY][current.first][current.second] == distances[obstacle.first][obstacle.second][current.first][current.second] && (obstacle.first != startX || obstacle.second != startY)) continue;
    for (int k = 0; k < 4; ++k)
    {
      pii next = {current.first + dx[k], current.second + dy[k]};
      if (isValid(next) && distances[startX][startY][next.first][next.second] == INF && distances[startX][startY][current.first][current.second] + 1 <= distances[obstacle.first][obstacle.second][next.first][next.second])
      {
        distances[startX][startY][next.first][next.second] = distances[startX][startY][current.first][current.second] + 1;
        bfsQueue.push(next);
      }
    }
  }
}

int main()
{
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  cin >> gridSize >> threshold;
  int startX, startY;
  for (int i = 0; i < gridSize; ++i)
    for (int j = 0; j < gridSize; ++j)
    {
      cin >> gridA[i][j];
      if (gridA[i][j] == 'Z') startX = i, startY = j;
    }
  for (int i = 0; i < gridSize; ++i)
    for (int j = 0; j < gridSize; ++j)
      cin >> gridB[i][j];
  obstacle = {startX, startY};
  bfs(startX, startY);
  for (int i = 0; i < gridSize; ++i)
    for (int j = 0; j < gridSize; ++j)
      distances[obstacle.first][obstacle.second][i][j] = min(distances[obstacle.first][obstacle.second][i][j], threshold);
  for (int i = 0; i < gridSize; ++i)
    for (int j = 0; j < gridSize; ++j)
      if (isValid({i, j})) bfs(i, j);
  source = 0;
  sink = 2 * gridSize * gridSize + 1;
  for (int i = 0; i < gridSize; ++i)
    for (int j = 0; j < gridSize; ++j)
    {
      if (gridA[i][j] != '0') insertEdge(source, i * gridSize + j + 1, gridA[i][j] - '0');
      if (gridB[i][j] != '0') insertEdge(i * gridSize + j + 1 + gridSize * gridSize, sink, gridB[i][j] - '0');
    }
  for (int i = 0; i < gridSize; ++i)
    for (int j = 0; j < gridSize; ++j)
      for (int i1 = 0; i1 < gridSize; ++i1)
        for (int j1 = 0; j1 < gridSize; ++j1)
          if (isValid({i, j}) && isValid({i1, j1}) && distances[i][j][i1][j1] <= distances[startX][startY][i1][j1])
            insertEdge(i * gridSize + j + 1, i1 * gridSize + j1 + 1 + gridSize * gridSize, INF);
  cout << dinicAlgorithm();
  return 0;
}
